"""Revenue per store day. See docs/store-days.md."""

from datetime import datetime, timedelta, timezone

from shoplib.errors import ShopError


def daily_revenue(sales: list[dict], utc_offset_hours: int = 8, day_starts_hour: int = 4) -> list[tuple[str, int]]:
    """Revenue per store day. See docs/store-days.md."""
    try:
        tz = timezone(timedelta(hours=utc_offset_hours))
    except (TypeError, ValueError) as exc:
        raise ShopError(f"invalid UTC offset: {utc_offset_hours}") from exc

    totals: dict = {}
    for sale in sales:
        try:
            at = datetime.fromisoformat(sale["at"])
        except (TypeError, ValueError) as exc:
            raise ShopError(f"invalid timestamp: {sale['at']}") from exc
        if at.tzinfo is None:
            raise ShopError(f"timestamp without a zone: {sale['at']}")
        day = (at.astimezone(tz) - timedelta(hours=day_starts_hour)).date()
        totals[day] = totals.get(day, 0) + sale["cents"]
    if not totals:
        return []
    out, day = [], min(totals)
    while day <= max(totals):
        out.append((day.isoformat(), totals.get(day, 0)))
        day += timedelta(days=1)
    return out
import pytest

from shoplib.errors import ShopError
from shoplib.storedays import daily_revenue


def test_day_starts_at_configured_local_hour():
    assert daily_revenue([
        {"at": "2026-11-18T03:59:59+08:00", "cents": 10},
        {"at": "2026-11-18T04:00:00+08:00", "cents": 20},
    ]) == [
        ("2026-11-17", 10),
        ("2026-11-18", 20),
    ]


def test_timezone_conversion_and_gap_days():
    assert daily_revenue([
        {"at": "2026-11-17T20:00:00Z", "cents": 125},
        {"at": "2026-11-20T04:00:00+08:00", "cents": -25},
    ]) == [
        ("2026-11-18", 125),
        ("2026-11-19", 0),
        ("2026-11-20", -25),
    ]


def test_no_sales_returns_empty_list():
    assert daily_revenue([]) == []


def test_timestamp_without_zone_raises_value_error():
    with pytest.raises(ValueError):
        daily_revenue([{"at": "2026-11-18T04:00:00", "cents": 10}])
